@@ -28,7 +35,10 @@ bool FolderComparator::LessThan(const RefPtr<Folder>& aA,
                                 const RefPtr<Folder>& aB) const {
   if (aA->mOrdinal.isNothing()) {
     if (aB->mOrdinal.isNothing()) {
-      return aA->mName < aB->mName;
+      const Collator* collator = GetCollator();
